import {readFile,writeFile} from 'node:fs/promises';
import {connectOperator} from '../tools/staging/m77-common';
import {hostedDumpEnvironment} from '../tools/staging/m78-hosted-database';
import {inventory} from '../tools/staging/m78-inventory';
const sha=(v:string)=>new Bun.CryptoHasher('sha256').update(v).digest('hex');
const hash=(v:unknown)=>sha(JSON.stringify(v));
function check(v:unknown):asserts v{if(!v)throw Error('Exact interrupted-session cleanup refused');}
const path='.superpowers/m78-interrupted-sessions-observed.json';
const text=await readFile(path,'utf8');
check(sha(text)==='4570ae628e05c71d8feab14acc6e5c04fe985f842ab2cdf8d111b19031d1f273');
const observed=JSON.parse(text);
check(observed.observations.length===4&&observed.observations.every((o:any)=>o.sessions.length===1&&o.refreshCounts.length===1&&o.refreshCounts[0].count==='1'));
const selected=observed.observations.map((o:any)=>({...o.sessions[0],role:o.role}));
check(new Set(selected.map((s:any)=>s.id)).size===4&&new Set(selected.map((s:any)=>s.user_id)).size===4);
const ids=selected.map((s:any)=>s.id);
const input=JSON.parse(await Bun.stdin.text());
check(input.operatorId==='/root'&&Object.keys(input).sort().join(',')==='operatorDatabaseUrl,operatorId');
hostedDumpEnvironment(input.operatorDatabaseUrl);
const intentPath='.superpowers/m78-interrupted-session-cleanup-intent.json';
await writeFile(intentPath,JSON.stringify({status:'cleanup_intent_only',createdAt:new Date().toISOString(),observationSha256:sha(text),selected,tokenUsability:'not_verified',expiryVerified:false},null,2)+'\n',{flag:'wx'});
const db=await connectOperator(input.operatorDatabaseUrl);
try{
 const result=await db.transaction(async tx=>{
  await tx.exec('set transaction isolation level serializable');
  const identity=(await tx.query<any>("select current_database() database,current_user actor,current_setting('transaction_isolation') isolation")).rows[0];
  check(identity.database==='postgres'&&identity.actor==='postgres'&&identity.isolation==='serializable');
  const fks=(await tx.query<any>("select conname,conrelid::regclass::text as child_table,confrelid::regclass::text as parent_table,pg_get_constraintdef(oid) as definition from pg_constraint where contype='f' and confrelid='auth.sessions'::regclass order by conname")).rows;
  check(fks.length===2&&fks.every((f:any)=>['auth.refresh_tokens','auth.mfa_amr_claims'].includes(f.child_table)&&f.parent_table==='auth.sessions'&&f.definition==='FOREIGN KEY (session_id) REFERENCES auth.sessions(id) ON DELETE CASCADE'));
  const triggers=(await tx.query<any>("select tgname from pg_trigger where not tgisinternal and tgrelid in ('auth.sessions'::regclass,'auth.refresh_tokens'::regclass,'auth.mfa_amr_claims'::regclass)")).rows;
  check(triggers.length===0);
  const sessionRows=async()=> (await tx.query<any>('select id,user_id,created_at,updated_at from auth.sessions order by id limit 10001')).rows;
  const linkedCounts=async(table:'refresh_tokens'|'mfa_amr_claims')=>(await tx.query<any>(`select session_id,count(*)::text as count from auth.${table} group by session_id order by session_id nulls first limit 10001`)).rows;
  const before=await sessionRows(),refreshBefore=await linkedCounts('refresh_tokens'),mfaBefore=await linkedCounts('mfa_amr_claims');
  check(before.length<=10000&&refreshBefore.length<=10000&&mfaBefore.length<=10000);
  const iso=(v:any)=>new Date(v).toISOString();
  for(const s of selected){
   const matches=before.filter((r:any)=>r.id===s.id);
   check(matches.length===1&&matches[0].user_id===s.user_id&&iso(matches[0].created_at)===s.created_at&&iso(matches[0].updated_at)===s.updated_at);
   check(refreshBefore.filter((r:any)=>r.session_id===s.id&&r.count==='1').length===1);
  }
  const appBefore=await inventory(tx);
  const deleted=[];
  for(const s of selected){
   const rows=(await tx.query<any>('delete from auth.sessions where id=$1 and user_id=$2 and created_at=$3::timestamptz and updated_at=$4::timestamptz returning id',[s.id,s.user_id,s.created_at,s.updated_at])).rows;
   check(rows.length===1&&rows[0].id===s.id);deleted.push(s.id);
  }
  const after=await sessionRows(),refreshAfter=await linkedCounts('refresh_tokens'),mfaAfter=await linkedCounts('mfa_amr_claims'),appAfter=await inventory(tx);
  check(!after.some((r:any)=>ids.includes(r.id))&&!refreshAfter.some((r:any)=>ids.includes(r.session_id))&&!mfaAfter.some((r:any)=>ids.includes(r.session_id)));
  check(hash(before.filter((r:any)=>!ids.includes(r.id)))===hash(after));
  check(hash(refreshBefore.filter((r:any)=>!ids.includes(r.session_id)))===hash(refreshAfter));
  check(hash(mfaBefore.filter((r:any)=>!ids.includes(r.session_id)))===hash(mfaAfter));
  check(hash(appBefore)===hash(appAfter));
  return {status:'m78_exact_interrupted_sessions_removed',observedAt:new Date().toISOString(),identity,observationSha256:sha(text),selected,deletedIds:deleted,sessionRowsRemoved:4,linkedRowsAbsent:true,nonselectedSessionsPreserved:true,nonselectedLinkedCountsPreserved:true,applicationInventorySha256:hash(appAfter),applicationWrites:0,applicationInventoryPreserved:true,tokenUsability:'not_verified',expiryVerified:false};
 });
 await writeFile('.superpowers/m78-interrupted-session-cleanup-result.json',JSON.stringify({...result,commitReturned:true},null,2)+'\n',{flag:'wx'});
 console.log(JSON.stringify({status:result.status,commitReturned:true,sessionRowsRemoved:4,linkedRowsAbsent:true,nonselectedSessionsPreserved:true,applicationWrites:0,tokenUsability:'not_verified'}));
}finally{await db.close();}

